resetEl.addEventListener('click', reset);

// 知识卡展开 / 收起（按钮为原生 button，可用 Tab 聚焦、Enter 或空格触发）
var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
var expandBtn = document.getElementById('expand-all');
var collapseBtn = document.getElementById('collapse-all');

function setAllCards(expanded) {
  cards.forEach(function (card) {
    card.classList.toggle('is-collapsed', !expanded);
    var fact = card.querySelector('.fact');
    if (fact) { fact.setAttribute('aria-hidden', expanded ? 'false' : 'true'); }
  });
  expandBtn.setAttribute('aria-pressed', String(expanded));
  collapseBtn.setAttribute('aria-pressed', String(!expanded));
}

expandBtn.addEventListener('click', function () { setAllCards(true); });
collapseBtn.addEventListener('click', function () { setAllCards(false); });
setAllCards(true);

build();
updateScore();

